int report_errorf(const char* format, ...);

struct SubRingSlotCursor {
    char subgame_prefix[offsetof(cRSubGame, ring_effects)];
    SubRing ring;
};

void cRSubGame::AddRing(
    cRSubLoc* cell,
    int requested_kind,
    cRSubGoldy* player,
    float ring_speed)
{
