            slot_cursor->ring.transform.position = staged_position;
            float random_x = RAND(1.0f, "RR8") - 0.5f;
            slot_cursor->ring.transform.position.x = (random_x + random_x) * 3.0f;
            SubRing* selected_ring = &slot_cursor->ring;
